:root {
  /* 主要文本 */
  --SmartThemeBodyColor: #000000;
  /* 斜体文本 */
  --SmartThemeEmColor: #505050;              /* ✏️【斜体色】灰黑色 */
  /* 下划线文本 */
  --SmartThemeUnderlineColor: #666666;       /* ✏️【下划线色】中灰色 */
  /* 引用文本 */
  --SmartThemeQuoteColor: #808080;           /* ✏️【引用色】中灰色 */
  /* 阴影颜色 */
  --SmartThemeShadowColor: rgba(0, 0, 0, 0.2); /* ✏️【阴影色】半透明黑 */
  /* 聊天背景 */
  --SmartThemeChatTintColor: #FFFFFF;        /* ✏️【聊天背景】白色 */
  /* UI背景 */
  --SmartThemeBlurTintColor: #F5F5F5;        /* ✏️【UI背景】浅灰 */
  /* UI边框 */
  --SmartThemeBorderColor: #CCCCCC;          /* ✏️【UI边框】浅灰 */
  /* 用户模糊色调 */
  --SmartThemeUserMesBlurTintColor: rgba(255, 255, 255, 0.9);
  /* AI模糊色调 */
  --SmartThemeBotMesBlurTintColor: rgba(255, 255, 255, 0.9);
}

body {
  font-family: , sans-serif !important;
  font-weight: normal;
  background-color: #FFFFFF !important;
  color: var(--SmartThemeBodyColor) !important;
}

#top-settings-holder {
  background: #FFFFFF !important;
  border-bottom: 1px solid #1E1E1E !important;  /* ✏️【顶栏边框】 */
}

#chat { background: transparent !important; }



/* =========================================
   🚩 气泡设置：【开始】
   ========================================= */

/* 1. 基础布局容器 (mes) */
.mes {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;

  /* ✨ 固定355px宽度 */
  width: 355px !important;
  max-width: 355px !important;
  /* ✏️【整体上下位置】上边距从260px改为235px，把整个气泡往上提，和顶部图配合好 */
  margin: 280px auto 140px !important; 

  /* 背景三段式 - 中间平铺 */
  background: url("https://i.postimg.cc/yYsDDM7Y/IMG_20260311_183400.png") repeat-y !important;
  background-size: 100% auto !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;

  /* 布局间距控制 */
  gap: 25px;
}

/* 2. 背景伪元素 (三段式切图：顶 & 底) */
.mes::before {
  content: "" !important;
  position: absolute !important;
  top: -247px !important;               /* ✏️【顶部位置】保持与顶部图片高度一致 */
  left: 0 !important;
  width: 100% !important;
  height: 247px !important;             /* ✏️【顶部高度】保持与图片原始高度一致 */
  background: url("https://i.postimg.cc/yYsDDM78/IMG_20260311_180809.png") no-repeat center bottom !important;
  background-size: contain !important;   /* 完整显示，不被拉伸 */
  background-position: center bottom !important;
  z-index: -1 !important;
}

.mes::after {
  content: "" !important;
  position: absolute !important;
  bottom: -247px !important;             /* ✏️【底部位置】改为和顶部一样的-247px */
  left: 0 !important;
  width: 100% !important;
  height: 247px !important;              /* ✏️【底部高度】改为和顶部一样的247px */
  background: url("https://i.postimg.cc/tCpssK9q/IMG_20260311_180854.png") no-repeat center top !important;
  background-size: contain !important;   /* 完整显示，不被拉伸 */
  background-position: center top !important;
  z-index: -1 !important;
}

/* 3. 头像与三元素容器 */
.mes .mesAvatarWrapper {
  position: absolute !important;
  top: -230px !important; 
  left: 35% !important;
  transform: translateX(-50%) !important;
  z-index: 2 !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  background: none !important;
  padding: 0 !important;
}

/* 4. 文本块布局  */
.mes_block {
    display: flex !important;
    flex-direction: column !important;

    /* 核心修改：让文字块宽度超过100%并向右强制拉伸 */
    width: calc(100% + 10px) !important;  /* ✏️【宽度拉伸】数值越大越往右突 */
    margin-left: 0 !important;
    margin-right: -20px !important;       /* ✏️【右突力度】负值越大越往右突 */
    margin-top: -90px !important;          /* ✏️【上移距离】负值越大越往上 */

    /* 内边距：控制文字距离背景边缘的真实距离 */
    padding: 15px 20px 15px 20px !important;      /* ✏️【文字边距】 */

    box-sizing: border-box !important;
    z-index: 1 !important;
    overflow: visible !important;
}

/* 5. 文字排版细节优化 */
.mes_text {
  color: var(--SmartThemeBodyColor) !important;
  line-height: 1.8 !important;
  word-wrap: break-word !important;
  text-align: justify !important;       /* ✏️【对齐方式】justify=两端对齐 */
  padding-right: 15px !important;       /* ✏️【文字右边距】防止文字贴边 */
}


/* =========================================
   🚩 头像样式 - 终极重置版（带标注）
   ========================================= */

/* 先清除所有可能的干扰 */
.mes .avatar,
.mesAvatarWrapper .avatar,
.mes .mesAvatarWrapper .avatar {
    all: initial !important;  /* 重置所有属性 */

    /* 重新设置需要的属性 */
    display: block !important;
    width: 119px !important;     /* ✏️【宽度】数字越大越宽 */
    height: 62px !important;     /* ✏️【高度】数字越大越高 */
    border-radius: 0px !important; /* ✏️【尖角】数字越大越圆 */
    overflow: hidden !important;   /* 裁剪圆角多余部分 */
    position: relative !important;

    /* 确保没有边框背景 */
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: none !important;
    background-color: transparent !important;
    background-image: none !important;
}

/* 头像图片 */
.mes .avatar img,
.mesAvatarWrapper .avatar img,
.mes .mesAvatarWrapper .avatar img {
    all: initial !important;  /* 重置所有属性 */

    /* 重新设置 */
    display: block !important;
    width: 100% !important;      /* 填满容器宽度 */
    height: 100% !important;      /* 填满容器高度 */
    object-fit: cover !important; /* 裁剪填充，保持比例 */
    object-position: center !important; /* 图片居中 */

    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
}

/* 头像容器父元素 */
.mes .mesAvatarWrapper {
    position: absolute !important;
    left: 72% !important;         /* ✏️【左右】数字越大越靠右，越小越靠左 */
    top: -96px !important;        /* ✏️【上下】负数往上移，正数往下移 */
    transform: translateX(-50%) !important;
    z-index: 2 !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    background: none !important;
    padding: 0 !important;
}

/* ===== 去除顶栏底部阴影和边框（保持背景纯净）===== */
#top-settings-holder,
#top-bar,
.drawer,
.drawer-header,
.drawer-icon {
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
  -moz-box-shadow: none !important;
  filter: none !important;
  -webkit-filter: none !important;
  border-bottom: none !important;
}



/* ===== 底栏图标替换 ===== */

#send_form [class*="fa-"]::before {
    content: '' !important;
    display: inline-block;
    width: 22px;              /* ✏️【图标宽度】 */
    height: 22px;             /* ✏️【图标高度】 */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
}

#options_button::before {
    background-image: url('https://i.postimg.cc/kXsBKT5J/wu_biao_ti281_20260311194630.png') !important;
}

#extensionsMenuButton::before {
    background-image: url('https://i.postimg.cc/rFjKxfpM/wu_biao_ti281_20260311195025.png') !important;
}

#quick-reply-rocket-button i::before {
    background-image: url('https://i.postimg.cc/rFjKxfpM/wu_biao_ti281_20260311195025.png') !important;
}

#send_but::before {
    background-image: url('https://i.postimg.cc/kXsBKT5J/wu_biao_ti281_20260311194630.png') !important;
}

#mes_stop i::before {
    background-image: url('https://i.postimg.cc/kXq2207G/wu_biao_ti281_20260311201333.png') !important;
}


/* 确保按钮容器本身不影响图标显示 */
.mes_buttons {
    display: flex !important;
    align-items: center !important;
    gap: 4px !important;                   /* ✏️【按钮间距】可调整 */
}

/* 世界书激活时按钮颜色 */
.world_set, 
.toggleEnabled {
    color: #C4C4C4 !important;    /* ✏️【世界书激活颜色】 */
}

/* 角色收藏时按钮颜色 */
.fav_on {
    color: #C4C4C4 !important;    /* ✏️【收藏激活颜色】 */
}

/* --- 1. 扩展面板/设置区的按钮和标题 --- */
.inline-drawer-toggle,
.standoutHeader,
.extension_button,
#user-settings-block h4,
.inline-drawer-header {
    /* 移除默认的灰色渐变背景 */
    background-image: none !important;

    /* 背景颜色 - 纯白 */
    background-color: #FFFFFF !important;

    /* 边框 - 黑 */
    border: 1px solid #C4C4C4 !important;  /* ✏️【边框】 */

    /* 文字颜色 - 黑色 */
    color: #848484 !important;              /* ✏️【文字颜色】灰黑色 */

    /* 其他美化样式 */
    border-radius: 12px !important;
    box-shadow: 0 2px 5px （128, 128, 128, 0.3） !important; /* ✏️【阴影】 */
}

/* 鼠标悬停时的样式 */
.inline-drawer-toggle:hover,
.extension_button:hover {
    border-color: #BDBDBD !important;
    box-shadow: 0 0 8px rgba(128, 128, 128, 0.3) !important;  /* ✏️【悬停阴影】 */
}


/* --- 2. 多选标签 (例如：世界书标签) --- */
.select2-container--default .select2-selection--multiple .select2-selection__choice {
    /* 移除默认的灰色渐变背景 */
    background-image: none !important;

    /* 背景颜色 - 纯白 */
    background-color: #FFFFFF !important;

    /* 边框 - 浅黑色 */
    border: 1px solid #A2A2A2 !important;   /* ✏️【标签边框】浅黑色 */

    /* 文字颜色 - 深黑色 */
    color: #101010 !important;               /* ✏️【标签文字】深黑色 */

    /* 圆角 */
    border-radius: 8px !important;
}

/* 整个多选框的容器样式 */
.select2-container--default .select2-selection--multiple {
    background-image: none !important;
    background-color: #FFFFFF !important;
    border: 1px solid #A5A3A3 !important;   /* ✏️【容器边框】浅灰色 */
    border-radius: 12px !important;
}

/* 当多选框被激活(点击)时的样式 */
.select2-container--default.select2-container--open .select2-selection--multiple {
    border-color: #FFFFFF !important;        /* ✏️【激活边框】白色 */
    box-shadow: 0 0 8px rgba(45, 45, 45, 0.79) !important;
}

/* ===== 全局白底设置 ===== */

/* 主背景设为白色 */
body {
    background-color: #FFFFFF !important;
}

/* 所有面板背景设为黑色 */
.drawer-content,
#left-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#rm_extensions_block,
#PersonaManagement,
#right-nav-panel {
    background-color: #FFFFFF !important;
    border-color: #1E1E1E !important;  /* ✏️【面板边框】改为浅黑 */
}

/* 输入框背景变白 */
select,
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
textarea {
    background-color: #FFFFFF !important;
    border: 1px solid #666666 !important;  /* ✏️【输入框边框】浅灰色 */
    color: #000000 !important;
}

/* 下拉菜单选项背景 */
option {
    background-color: #FFFFFF !important;
    color: #000000 !important;
}

/* 按钮背景变浅 */
.menu_button,
.api_button {
    background-color: #666666 !important;  /* ✏️【按钮背景】改为 lavenderblush  */
    border: 1px solid #666666 !important;   /* ✏️【按钮边框】 */
    color: #2A2A2A !important;               /* ✏️【按钮文字】 */
}

/* 按钮悬停效果 */
.menu_button:hover,
.api_button:hover {
    background-color: #505050 !important;  /* ✏️【悬停背景】更深的浅灰 */
}

/* 消息区域背景 */
.mes {
    background-color: rgba(255, 255, 255, 0.9) !important;
}


/* 顶栏背景 */
#top-settings-holder {
    background-color: #FFFFFF !important;
    border-bottom: 1px solid #505050 !important;  /* ✏️【顶栏边框】浅灰色 */
}

/* 如果背景图导致透出黑色，可以临时注释掉背景图 */
/* #top-settings-holder {
    background-image: none !important;
} */

/* ===== 顶栏：图标可点击 + 底部背景图片 ===== */

/* 顶栏容器 - 背景图片 */
#top-settings-holder {
    background-image: url('https://i.postimg.cc/HsdrrqTj/IMG_20260311_192346.png') !important;
    background-size: 100% 100% !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    border-bottom: none !important;
    min-height: 35px !important;
    position: relative !important;
}

/* 图标容器 - 负责点击 */
#top-settings-holder .drawer-icon {
    opacity: 1 !important;
    pointer-events: auto !important;
    position: relative !important;
    z-index: 5 !important;
    display: inline-block !important;
    width: 25px !important;                 /* ✏️【点击区域宽度】稍微调小 */
    height: 25px !important;                /* ✏️【点击区域高度】稍微调小 */
    background: transparent !important;
}

/* 图标图片 - 只负责显示，不负责点击 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    background-color: transparent !important;
    z-index: 4 !important;
    transition: transform 0.3s ease-in-out;
}

/* 悬停效果 - 作用于图片 */
#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.1);
}

/* ===== 图标图片分配===== */

/* 图标1: AI响应配置  */
#leftNavDrawerIcon::before {
    background-image: url('https://i.postimg.cc/wT27LwBT/wu_biao_ti280_20260311193626.png') !important;
}

/* 图标2: API连接 */
#API-status-top::before {
    background-image: url('https://i.postimg.cc/jdtDDpR5/1773226596146.png') !important;
}

/* 图标3: AI回复格式化 */
.drawer-icon.fa-font::before {
    background-image: url('https://i.postimg.cc/28GVh05C/wu_biao_ti280_20260311193308.png') !important;
}

/* 图标4: 世界信息/世界书 */
#WIDrawerIcon::before {
    background-image: url('https://i.postimg.cc/kXsBKT59/wu_biao_ti280_20260311193355.png') !important;
}

/* 图标5: 用户设置  */
.drawer-icon.fa-user-cog::before,
.drawer-icon.fa-user::before {
    background-image: url('https://i.postimg.cc/jdtDDpR5/1773226596146.png') !important;
}

/* 图标6: 背景图片  */
#backgrounds-drawer-toggle .drawer-icon::before {
    background-image: url('https://i.postimg.cc/28GVh05C/wu_biao_ti280_20260311193308.png') !important;
}

/* 图标7: 扩展 */
.drawer-icon.fa-cubes::before {
    background-image: url('https://i.postimg.cc/kXsBKT59/wu_biao_ti280_20260311193355.png') !important;
}

/* 图标8: 用户角色管理  */
.drawer-icon.fa-face-smile::before {
    background-image: url('https://i.postimg.cc/28GVh05C/wu_biao_ti280_20260311193308.png') !important;
}

/* 图标9: 角色卡  */
#rightNavDrawerIcon::before {
    background-image: url('https://i.postimg.cc/qMwzy17v/wu_biao_ti280_20260311193822.png') !important;
}

/* 图标10: 时光记忆 (右) - 新增扩展 */
#horae_drawer .drawer-icon::before {
    background-image: url('https://i.postimg.cc/jdtDDpR5/1773226596146.png') !important;
}

/* 悬停效果微调 */
#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.1);
}

/* ===== 去除顶栏底部阴影和边框 ===== */
#top-settings-holder,
#top-bar,
.drawer,
.drawer-header,
.drawer-icon {
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
  -moz-box-shadow: none !important;
  filter: none !important;
  -webkit-filter: none !important;
  border-bottom: none !important;
}

/* ===== 隐藏全部滚动条 ===== */
::-webkit-scrollbar {
 display: none;
}



/* ===== 移除预设开关键阴影 ===== */

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
    filter: none !important;
    box-shadow: none !important;
    -webkit-box-shadow: none !important;
    -moz-box-shadow: none !important;
}

/* ===== 消息编辑菜单按钮 - 控制位置 + 移除阴影 ===== */

/* 消息编辑按钮容器（如果有） */
.mes_buttons {
    flex-direction: row !important;
    column-gap: 5px !important;
    float: right !important;
    cursor: pointer !important;
    padding-bottom: 5px !important;
    filter: none !important;
    transition: 0.3s ease-in-out !important;
    box-shadow: none !important;
    -webkit-box-shadow: none !important;
    -moz-box-shadow: none !important;
}

/* 编辑菜单位置核心调整 */
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable,
.mes_edit_down.menu_button.fa-solid.fa-chevron-down {
    filter: none !important;
    box-shadow: none !important;
    -webkit-box-shadow: none !important;
    -moz-box-shadow: none !important;

    /* ⭕编辑菜单位置核心调整⭕ */
    position: relative !important;
    top: 120px !important;   /* ✏️【上下位置】负数上移，正数下移 */
    right: 155px !important; /* ✏️【左右位置】负数右移，正数左移 */
    transform: rotate(0deg) !important; /* 旋转角度 */
}

/* 禁用状态的按钮也移除阴影 */
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable.disabled {
    filter: none !important;
    box-shadow: none !important;
    -webkit-box-shadow: none !important;
    -moz-box-shadow: none !important;
