    color: transparent !important;
    width: 24px !important;                /* ✏️【图标宽度】数字越大越宽 */
    height: 24px !important;               /* ✏️【图标高度】数字越大越高 */
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    opacity: 1 !important;
    transition: transform 0.2s ease !important;
    display: inline-block !important;

    /* 确保容器有定位上下文 */
    position: relative !important;
    overflow: hidden !important;

    /* 移除任何可能的文本 */
    font-size: 0 !important;
    text-indent: -9999px !important;
}

/* 铅笔图标替换 */
.mes_edit {
    background-image: url('https://i.postimg.cc/rFjKxfpM/wu_biao_ti281_20260311195025.png') !important;
}

/* 展开图标替换 */
.extraMesButtonsHint {
    background-image: url('https://i.postimg.cc/rFjKxfpM/wu_biao_ti281_20260311195025.png') !important;
}

/* 悬停效果 */
.mes_edit:hover, 
.extraMesButtonsHint:hover {
    transform: scale(1.1) !important;
}

/* 确保没有其他伪元素干扰 */
.mes_edit::after,
.extraMesButtonsHint::after {
    display: none !important;
}


/* 对话块 (q) 美化 - 融入段落 */
.mes_text q, .mes_text blockquote {
  display: inline !important;        /* ✏️【关键】从block改为inline，让引号内容融入段落 */
  color: var(--SmartThemeQuoteColor) !important;
  border-left: none !important;
  background: none !important;
  padding: 0 !important;
  margin: 0 !important;              /* 去掉上下边距 */
  font-style: normal !important;
}

/* 对话块 (q) 美化 - 融入段落 */
.mes_text q, .mes_text blockquote {
  display: inline !important;
  color: #808080 !important;        /* ✏️【引用色】改成中灰色，数字越小越深，越大越浅 */
  border-left: none !important;
  background: none !important;
  padding: 0 !important;
  margin: 0 !important;
  font-style: normal !important;
}


/* ===== 页面加载动画美化 - 全屏图片版 ===== */

#preloader {
  position: fixed;
  margin: 0;
  padding: 0;
  top: 0;
  left: 0;
  z-index: 999999;
  width: 100vw;
  height: 100vh;
  /* ✏️【背景图片】整页加载图 */
  background-image: url('https://i.postimg.cc/5NpKTQg2/Screenshot-2026-0311-221954.png') !important;
  background-size: cover;        /* ✏️【填充方式】cover=铺满可能裁剪，contain=完整显示可能有留白 */
  background-position: center;
  background-repeat: no-repeat;
  opacity: 1;
}

/* 隐藏原来的加载图标，因为不要了 */
#load-spinner {
  display: none !important;
}


/* ===== 斜体文字美化 ===== */

/* 斜体文字 - 灰黑色 + 波浪下划线 */
.mes_text em, 
.mes_text i {
    color: #505050 !important;        /* ✏️【斜体颜色】灰黑色，不要太浅（可调） */
    font-style: italic !important;     /* 斜体 */
    text-decoration: underline wavy #808080 !important;  /* ✏️【波浪下划线】颜色中灰色 */
    text-underline-offset: 2px !important;  /* 下划线与文字的距离 */
}

/* 如果只想给某些特定斜体加波浪线，可以用这个 */
.mes_text em.important,
.mes_text i.important {
    text-decoration: underline wavy #808080 !important;
}

/* 消息按钮整列（铅笔、收藏、展开等） - 整体下移 */
.mes_buttons {
    margin-top: 25px !important;        /* ✏️【下移距离】正数下移，负数上移 */
}

/* 时间戳 - 下移 */
.mes .timestamp {
    margin-top: 30px !important;        /* ✏️【时间下移】和按钮保持一致 */
}


/* ===== Star插件 - 消息收藏按钮版 ===== */

/* 1. 消息上的星星图标（未收藏状态） */
.mes .mes_buttons .fa-star,
.mes .extraMesButtons .fa-star {
    color: #ABABAB !important;  /* */
}


/* ===== 底栏悬浮效果 ===== */

/* 美化文本输入区域 */
#send_textarea {
    /* 允许文本框填充剩余空间，并随内容自动调整高度 */
    flex-grow: 1 !important;
    /* 最小高度，使其与图标保持一致 */
    min-height: 24px !important; 
    /* 移除多余的行高，防止文字将输入框撑高 */
    line-height: 1.5 !important; 

    /* 顶部边框完整显示 */
    clip-path: none !important; 
    /* 隐藏容器视觉效果，确保外层圆角能显示 */
    background-color: transparent !important;
    border-color: transparent !important;
    /* 内部文本框也需要圆角，否则会遮挡底部圆角 */
    border-radius: 16px !important;
}

/* 确保输入框固定在底部 */
#form_sheld {
    position: sticky !important;
    bottom: 100px !important;           /* ✏️【底部距离】可调 */
    transition: transform 0.3s ease !important;
}

/* 鼠标悬浮在整个底部区域时，向上平移 */
#form_sheld:hover {
    transform: translateY(-5px) !important;  /* ✏️【悬浮上移距离】可调 */
}

/* 布局调整，让内容占满屏幕 */
#sheld, 
#chat {
    height: calc(100dvh + var(--bottomFormBlockSize)) !important;
    max-height: calc(100dvh + var(--bottomFormBlockSize)) !important;
}

/* 最后一条消息与底部间距 */
.last_mes {
    margin-bottom: 150px !important;    /* ✏️【底部留白】可调 */
}

/* QR-bar 样式 - 确保其定位优先级最高 */
#qr--bar {
    position: absolute !important;
    bottom: calc(100% + 5px) !important; 
    right: 0 !important;

    /* 初始状态：完全隐藏 */
    opacity: 0 !important;
    height: 0 !important;
    overflow: hidden !important;

    /* 平滑过渡 */
    transition: opacity 0.5s ease, height 0.5s ease !important;
}

/* 悬停时显示效果 */
#send_form:hover #qr--bar,
#send_form:focus-within #qr--bar {
    opacity: 1 !important;
    height: auto !important;
}

/* ===== 行内代码美化 - 纯图片背景 ===== */

/* 行内代码 - 只要图片背景，不要框 */
:not(pre) > code {
    /* 背景图设置 */
    background-image: url('https://i.postimg.cc/h4NWrtcq/IMG_20260319_120908.png') !important;
    background-size: cover !important;              /* ✏️【背景填充】cover=铺满，contain=完整显示 */
    background-position: 50% 50% !important;        /* ✏️【图片上下左右】第一个%左右，第二个%上下（0%靠上，50%居中，100%靠下） */
    background-repeat: no-repeat !important;
    background-color: transparent !important;

    /* ✏️【整体大小】数字越大背景图区域越大 */
    padding: 10px 10px !important;                    /* 上下10px，左右10px - 让背景图更大 */
    font-size: 12px !important;                      /* ✏️【字体大小】数字越大字越大 */

    /* 去掉所有框线 */
    border: none !important;
    outline: none !important;
    box-shadow: none !important;

    /* 文字颜色和字体 */
    color: #333333 !important;
    font-family: monospace !important;

    /* 文字阴影，让字在图片上清晰点 */
    text-shadow: 0 0 2px rgba(255, 255, 255, 0.8) !important;
}

/* 去掉悬停效果 */
:not(pre) > code:hover {
    transform: none !important;
}


/* ===== 输入框提示文字自定义 ===== */

#nonQRFormItems {
    position: relative;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "あたしをグレッチで殴って" !important;  /* ✏️【提示文字】你指定的日语 */
    color: #808080 !important;                         /* ✏️【文字颜色】中灰 */
    position: absolute;
    left: 58% !important;                               /* ✏️【左右位置】 */
    top: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-size: 11px !important;                         /* ✏️【字体大小】 */
    letter-spacing: 0.5px !important;                   /* ✏️【字间距】 */
    opacity: 0.6 !important;                             /* ✏️【透明度】 */
    font-style: normal !important;                       /* ✏️【字体样式】normal或italic */
    pointer-events: none !important;
    z-index: 10 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    max-width: calc(100% - 60px) !important;
    background: transparent !important;
    border: none !important;
}


